using System;using System.IO;using System.Linq;using System.Collections.Generic;using ModStatistik;
class RecorderTests{
static void Need(bool value,string message){if(!value)throw new Exception(message);}
static int Main(string[] args){try{
string dir=Path.Combine(args[0],Guid.NewGuid().ToString("N"));var recorder=new BloodmoonRecorder(dir,"world");string log=Path.Combine(dir,"bloodmoon_kills.txt");Need(File.Exists(log)&&BloodmoonLog.Parse(File.ReadAllText(log)).Nights.Count==0,"file created");int calls=0;long a=100,b=20;bool online=true;Func<IEnumerable<KillSample>> samples=()=>{calls++;var list=new List<KillSample>{new KillSample("a","Alpha",a)};if(online)list.Add(new KillSample("b","Beta",b));return list;};ulong start=6UL*24000+22000;ulong end=7UL*24000+4000;
recorder.Step(start-1,7,22,4,0,samples);Need(calls==0,"no counter query before start");recorder.Step(start,7,22,4,1,samples);Need(recorder.Active&&calls==1,"22 start");a=103;b=22;recorder.Step(start+1,7,22,4,7,samples);recorder.Capture(samples());recorder=new BloodmoonRecorder(dir,"world");a=105;online=false;recorder.Step(start+2,14,22,4,8,samples);a=1;recorder.Step(start+3,14,22,4,9,samples);a=3;recorder.Step(end,14,22,4,10,samples);var night=BloodmoonLog.Parse(File.ReadAllText(log)).Nights.Single();Need(night.Day==7&&night.Kills["Alpha"]==7&&night.Kills["Beta"]==2,"resume midnight offline reset final counters");int previous=calls;recorder.Step(end+1,14,22,4,11,samples);Need(calls==previous,"no daytime counter query");recorder=new BloodmoonRecorder(dir,"world");recorder.Step(start,7,22,4,12,samples);Need(!recorder.Active&&calls==previous,"duplicate night prevented");Need(File.ReadAllText(log).Split(new[]{" END "},StringSplitOptions.None).Length==2,"single END");
string join=Path.Combine(args[0],Guid.NewGuid().ToString("N"));var jr=new BloodmoonRecorder(join,"world");jr.Step(start,7,22,4,0,()=>new KillSample[0]);jr.Step(start+1,7,22,4,1,()=>new[]{new KillSample("x","Late",50)});jr.Step(end,7,22,4,2,()=>new[]{new KillSample("x","Late",53)});Need(BloodmoonLog.Parse(File.ReadAllText(Path.Combine(join,"bloodmoon_kills.txt"))).Nights.Single().Kills["Late"]==3,"late join baseline");
string bad=Path.Combine(args[0],Guid.NewGuid().ToString("N"));Directory.CreateDirectory(bad);File.WriteAllText(Path.Combine(bad,"bloodmoon_kills.txt"),"broken");new BloodmoonRecorder(bad,"world");Need(Directory.GetFiles(bad,"*.bak").Length==1&&File.ReadAllText(Directory.GetFiles(bad,"*.bak")[0])=="broken","corrupt TXT saved");
string deleted=Path.Combine(args[0],Guid.NewGuid().ToString("N"));var dr=new BloodmoonRecorder(deleted,"world");dr.Step(start,7,22,4,0,()=>new[]{new KillSample("x","X",0)});File.Delete(Path.Combine(deleted,"bloodmoon_kills.txt"));dr.Step(end,7,22,4,1,()=>new[]{new KillSample("x","X",4)});Need(BloodmoonLog.Parse(File.ReadAllText(Path.Combine(deleted,"bloodmoon_kills.txt"))).Nights.Single().Total==4,"deleted TXT restored at END");string history=Path.Combine(args[0],Guid.NewGuid().ToString("N"));Directory.CreateDirectory(history);File.Copy(args[1],Path.Combine(history,"bloodmoon_kills.txt"));var hr=new BloodmoonRecorder(history,"world");hr.Step(start,7,22,4,0,()=>new[]{new KillSample("x","X",10)});hr.Step(end,7,22,4,1,()=>new[]{new KillSample("x","X",12)});var old=BloodmoonLog.Parse(File.ReadAllText(Path.Combine(history,"bloodmoon_kills.txt")));Need(old.Nights.Count==3&&old.Nights[0].Total==385&&old.Nights[1].Total==274&&old.Nights[2].Total==2,"history preserved");
string damaged=Path.Combine(args[0],Guid.NewGuid().ToString("N"));Directory.CreateDirectory(damaged);File.WriteAllText(Path.Combine(damaged,"bloodmoon_state-world.json"),"broken");bool failed=false;try{new BloodmoonRecorder(damaged,"world");}catch(Exception){failed=true;}Need(failed&&File.ReadAllText(Path.Combine(damaged,"bloodmoon_state-world.json"))=="broken","invalid state preserved and stopped");
Console.WriteLine("PASS: TXT creation, no counters outside bloodmoon, start/end, final sample, restart, midnight, offline, counter reset, late join, duplicate prevention, corruption backup, deleted TXT.");return 0;
}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
